        // No leftover temp files
        let temp_path = path.with_extension("tmp");
        assert!(!temp_path.exists());
    }

    #[test]
    fn concurrent_stores_produce_valid_entries() {
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));

        // Spawn multiple threads that all write to the same cache entry
        let handles: Vec<_> = (0..10)
            .map(|i| {
                let store = Arc::clone(&store);
                thread::spawn(move || {
                    let content = format!("content-from-thread-{}", i);
                    store
                        .store("http:test", "shared-template", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        // The entry must be loadable and its content must be valid
        // (from one of the threads, not a corrupted mix)
        let entry = store.load("http:test", "shared-template").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();
        assert!(
            content.starts_with("content-from-thread-"),
            "Content was corrupted: {:?}",
            content
        );
    }

    #[test]
    fn concurrent_stores_to_different_entries() {
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));

        let handles: Vec<_> = (0..10)
            .map(|i| {
                let store = Arc::clone(&store);
                thread::spawn(move || {
                    let name = format!("template-{}", i);
                    let content = format!("content-{}", i);
                    store
                        .store("http:test", &name, &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        let entries = store.list().unwrap();
        assert_eq!(entries.len(), 10);

        // Each entry should have valid, parseable metadata and matching content
        for entry in &entries {
            let content = store.read_content(entry).unwrap();
            assert!(content.starts_with("content-"));
        }
    }
}

